<script>
document.getElementById('advisor-preview').addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget,button=form.querySelector('button'),out=document.getElementById('advisor-preview-result');button.disabled=true;out.textContent=<?= json_encode(fcc_t('Pripremam odgovor…')) ?>;try{const r=await fetch(<?= json_encode(url('fcc-ai/advisor-preview')) ?>,{method:'POST',body:new URLSearchParams(new FormData(form))});const j=await r.json();out.textContent='';if(j.status!=='success')throw Error(j.message||'Error');const p=document.createElement('p');p.textContent=j.details.answer;out.append(p);for(const a of j.details.actions||[]){const el=document.createElement('a');el.className='fah-button';el.href=a.url;el.target='_blank';el.rel='noopener noreferrer';el.textContent=a.title;out.append(el);if(a.draft){const draft=document.createElement('textarea');draft.rows=7;draft.value=a.draft;draft.setAttribute('aria-label',a.title);out.append(draft);const update=()=>{const u=new URL(a.url);u.searchParams.set('text',draft.value);el.href=u.href;};draft.addEventListener('input',update);update();}}}catch(err){out.textContent=err.message;}finally{button.disabled=false;}});
</script>
