<script>document.querySelectorAll('.advisor-review').forEach(form=>form.addEventListener('submit',async e=>{e.preventDefault();const button=form.querySelector('button'),status=form.querySelector('[role=status]');button.disabled=true;try{const r=await fetch(<?= json_encode(url('fcc-ai/advisor-feedback')) ?>,{method:'POST',body:new URLSearchParams(new FormData(form))});const j=await r.json();status.textContent=j.message||'';if(j.status!=='success')button.disabled=false;}catch(err){status.textContent=<?= json_encode(fcc_t('Pokušaj ponovno.')) ?>;button.disabled=false;}}));</script>
